:root {
  color-scheme: light;
  --ink: #1f2937;
  --muted: #6b7280;
  --line: #e5e7eb;
  --brand: #0f766e;
  --brand-ink: #ffffff;
  --bg: #f9fafb;
  --card: #ffffff;
  --focus: #1d4ed8;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
}

#app {
  max-width: 640px;
  margin: 0 auto;
  padding: 1.5rem 1rem 4rem;
}

.app-header h1 {
  margin: 0 0 0.15rem;
  font-size: 1.75rem;
}

.tagline {
  margin: 0 0 1.5rem;
  color: var(--muted);
}

#note-form {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  margin-bottom: 1.75rem;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

.field label {
  font-weight: 600;
  font-size: 0.9rem;
}

input[type="text"],
input[type="search"],
textarea {
  font: inherit;
  padding: 0.5rem 0.6rem;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
  color: inherit;
  width: 100%;
}

textarea {
  resize: vertical;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.9rem;
}

input:focus-visible,
textarea:focus-visible,
button:focus-visible,
.note-title:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.hint {
  margin: 0;
  font-size: 0.8rem;
  color: var(--muted);
}

.hint code {
  background: #f1f5f9;
  padding: 0.05rem 0.3rem;
  border-radius: 4px;
}

button[type="submit"] {
  align-self: flex-start;
  background: var(--brand);
  color: var(--brand-ink);
  border: none;
  padding: 0.55rem 1.1rem;
  border-radius: 8px;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

button[type="submit"]:hover {
  filter: brightness(0.95);
}

.search-row {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin-bottom: 0.35rem;
}

.search-row label {
  font-weight: 600;
  font-size: 0.9rem;
}

#results-line {
  min-height: 1.1rem;
  margin: 0 0 1rem;
  color: var(--muted);
  font-size: 0.9rem;
}

#feed {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.note {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 0.85rem 1rem;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.15rem 0.75rem;
}

.note[aria-current="true"] {
  border-color: var(--brand);
  box-shadow: 0 0 0 1px var(--brand);
}

.note-avatar {
  grid-row: 1 / span 2;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  object-fit: cover;
}

.note h2 {
  margin: 0;
  font-size: 1.05rem;
  grid-column: 2;
}

.note:has(.note-avatar) h2,
.note:has(.note-avatar) .note-body,
.note:has(.note-avatar) .note-date {
  grid-column: 2;
}

.note:not(:has(.note-avatar)) h2,
.note:not(:has(.note-avatar)) .note-body,
.note:not(:has(.note-avatar)) .note-date {
  grid-column: 1 / -1;
}

.note-title {
  background: none;
  border: none;
  font: inherit;
  font-weight: 700;
  color: var(--ink);
  padding: 0;
  cursor: pointer;
  text-align: left;
}

.note-title:hover {
  color: var(--brand);
  text-decoration: underline;
}

.note-body {
  margin: 0.3rem 0 0;
  line-height: 1.45;
  word-wrap: break-word;
}

.note-body a {
  color: var(--focus);
}

.note-date {
  display: block;
  margin-top: 0.35rem;
  font-size: 0.78rem;
  color: var(--muted);
}

.empty-state {
  color: var(--muted);
  text-align: center;
  padding: 2rem 0;
}

