function renderRichText(raw: string): string {
  let out = '';
  let lastIndex = 0;
  let match: RegExpExecArray | null;
  ALLOWED_TAG_RE.lastIndex = 0;
  while ((match = ALLOWED_TAG_RE.exec(raw))) {
    out += escapeHtml(raw.slice(lastIndex, match.index));
