import { spawn, spawnSync } from 'node:child_process';
import path from 'node:path';
import { chromium } from '@playwright/test';

const dir = process.cwd();
const port = 4700 + Math.floor(Math.random() * 200);
const server = spawn('node', [path.join(dir, 'server.mjs'), '--port', String(port)], { cwd: dir, stdio: 'inherit' });
await new Promise((r) => setTimeout(r, 500));

const browser = await chromium.launch();
const page = await browser.newPage();
page.on('pageerror', (e) => console.log('pageerror:', e.message));

const base = `http://127.0.0.1:${port}/`;

// 1. initial load, seeded notes, newest first
await page.goto(base, { waitUntil: 'load' });
const ids = await page.$$eval('#feed article.note', els => els.map(e => e.dataset.noteId));
console.log('order:', ids);

// check rich text rendering
const firstBodyHtml = await page.$eval('article.note[data-note-id="6"] .note-body', el => el.innerHTML);
console.log('note6 body html:', firstBodyHtml);
const linkHref = await page.$eval('article.note[data-note-id="4"] .note-body a', el => el.getAttribute('href'));
console.log('note4 link href:', linkHref);
const boldTag = await page.$eval('article.note[data-note-id="6"] .note-body b', el => el.tagName);
console.log('bold tag found:', boldTag);

// 2. search
await page.fill('#search', 'douro');
await page.waitForTimeout(100);
const resultsLine = await page.$eval('#results-line', el => el.textContent);
console.log('results-line:', JSON.stringify(resultsLine));
const filteredIds = await page.$$eval('#feed article.note', els => els.map(e => e.dataset.noteId));
console.log('filtered ids:', filteredIds);
console.log('hash after search:', await page.evaluate(() => location.hash));

// 3. click a note title
await page.click('article.note[data-note-id="5"] .note-title');
await page.waitForTimeout(100);
console.log('hash after select:', await page.evaluate(() => location.hash));
const ariaCurrent = await page.$eval('article.note[data-note-id="5"]', el => el.getAttribute('aria-current'));
console.log('aria-current on 5:', ariaCurrent);

// 4. reload and check restore
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(100);
console.log('search value after reload:', await page.$eval('#search', el => el.value));
console.log('results-line after reload:', await page.$eval('#results-line', el => el.textContent));
const ariaCurrent2 = await page.$eval('article.note[data-note-id="5"]', el => el.getAttribute('aria-current'));
console.log('aria-current on 5 after reload:', ariaCurrent2);

// 5. add a new note with rich text
await page.fill('#search', '');
await page.waitForTimeout(50);
await page.fill('#title', 'Test Note');
await page.fill('#body', 'Hello <b>world</b>\nsecond line <a href="https://example.com">link</a>');
await page.fill('#avatar', '');
await page.click('#note-form button[type=submit]');
await page.waitForTimeout(100);
const newIds = await page.$$eval('#feed article.note', els => els.map(e => e.dataset.noteId));
console.log('ids after add:', newIds);
const titleCleared = await page.$eval('#title', el => el.value);
console.log('title cleared:', JSON.stringify(titleCleared));
const newBodyHtml = await page.$eval(`article.note[data-note-id="${Math.max(...newIds.map(Number))}"] .note-body`, el => el.innerHTML);
console.log('new note body html:', newBodyHtml);

// 6. XSS check - malicious input
await page.fill('#title', 'XSS Test');
await page.fill('#body', '<img src=x onerror=alert(1)><script>alert(2)</script>');
await page.click('#note-form button[type=submit]');
await page.waitForTimeout(100);
const xssIds = await page.$$eval('#feed article.note', els => els.map(e => e.dataset.noteId));
const xssBodyHtml = await page.$eval(`article.note[data-note-id="${Math.max(...xssIds.map(Number))}"] .note-body`, el => el.innerHTML);
console.log('xss note body html:', xssBodyHtml);

// 7. persistence across reload
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(100);
const persistedIds = await page.$$eval('#feed article.note', els => els.map(e => e.dataset.noteId));
console.log('ids after reload (persisted):', persistedIds);

await browser.close();
server.kill();
